def moore_bound(d, g):
    if g % 2 == 1:
        k = (g - 1) // 2
        return 1 + d * sum((d - 1)**i for i in range(k))
    else:
        k = g // 2
        return 2 * sum((d - 1)**i for i in range(k))

print(f"Moore bound for d=5, g=6: {moore_bound(5, 6)}")
print(f"Moore bound for d=3, g=6: {moore_bound(3, 6)}")
print(f"Moore bound for d=4, g=6: {moore_bound(4, 6)}")

import random

def get_neighbors(adj, u):
    return [v for v, connected in enumerate(adj[u]) if connected]

def has_path_of_length_less_than_5(adj, u, v):
    # Check path of length 1: u-v
    if adj[u][v]: return True

    # Check path of length 2: u-w-v
    for w in range(25):
        if adj[u][w] and adj[w][v]: return True

    # Check path of length 3: u-w-x-v
    for w in range(25):
        if adj[u][w]:
            for x in range(25):
                if adj[w][x] and adj[x][v]: return True

    # Check path of length 4: u-w-x-y-v
    for w in range(25):
        if adj[u][w]:
            for x in range(25):
                if adj[w][x]:
                    for y in range(25):
                        if adj[x][y] and adj[y][v]: return True
    return False

def solve():
    for _ in range(100):
        adj = [[False for _ in range(25)] for _ in range(25)]
        degrees = [0 for _ in range(25)]
        edges = []

        possible_edges = []
        for i in range(25):
            for j in range(i + 1, 25):
                possible_edges.append((i, j))
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if degrees[u] < 6 and degrees[v] < 6:
                if not has_path_of_length_less_than_5(adj, u, v):
                    adj[u][v] = adj[v][u] = True
                    degrees[u] += 1
                    degrees[v] += 1
                    edges.append((u, v))

        if all(d >= 5 for d in degrees):
            return edges
    return None

result = solve()
print(result)
